using UnityEngine;
using UnityEditor;
using UnityEngine.SceneManagement;
using System;
using System.IO;
using System.Linq;
using ConRoi.Investigation.V36.R107;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            if (Application.dataPath.Replace('\\', '/') != "C:/ConRoi_CheckoutTest/Assets")
                throw new Exception("Wrong project");
            var s = UnityEngine.Object.FindFirstObjectByType<InvestigationSession>();
            if (!s || !s.SavePath.Contains("Clean_20261107"))
                throw new Exception("Wrong profile");
            if (Enumerable.Range(0, SceneManager.sceneCount).Any(i => SceneManager.GetSceneAt(i).isDirty))
                throw new Exception("Dirty: preserve without closing");
            File.WriteAllText("Test/Output/CleanCheckout/pre-stop-final-state.json", JsonUtility.ToJson(s.data, true));
            EditorApplication.isPlaying = false;
            double since = EditorApplication.timeSinceStartup;
            EditorApplication.CallbackFunction f = null;
            f = () =>
            {
                if (EditorApplication.isPlaying || EditorApplication.timeSinceStartup - since < 4)
                    return;
                EditorApplication.update -= f;
                if (Enumerable.Range(0, SceneManager.sceneCount).Any(i => SceneManager.GetSceneAt(i).isDirty))
                {
                    File.WriteAllText("Test/Output/CleanCheckout/controlled-close.txt", "BLOCKED dirty Edit scene");
                    return;
                }

                File.WriteAllText("Test/Output/CleanCheckout/controlled-close.txt", "Play stopped after state/diff snapshot. No scene save. Edit clean; exit.");
                EditorApplication.Exit(0);
            };
            EditorApplication.update += f;
            r.Log("Controlled stop queued after preserved snapshot");
        }
    }
}

